<?php declare(strict_types=1);require dirname(__DIR__,2).'/includes/bootstrap.php';require_permission('admins.view');
if(is_post()){require_permission('admins.create');verify_csrf();$name=trim((string)input('name'));$username=trim((string)input('username'));$email=filter_var(input('email'),FILTER_VALIDATE_EMAIL);$password=(string)input('password');$role=(int)input('role_id');if(!$name||strlen($name)>120||!preg_match('/^[A-Za-z0-9._-]{3,80}$/',$username)||!$email||strlen($password)<12)flash('error','Valid details and a password of at least 12 characters are required.');else{$pdo=db();$pdo->beginTransaction();try{$check=$pdo->prepare('SELECT id FROM admin_roles WHERE id=?');$check->execute([$role]);if(!$check->fetch())throw new RuntimeException('Invalid administrator role.');$pdo->prepare('INSERT INTO admins(role_id,name,username,email,password_hash,status) VALUES(?,?,?,?,?,"ACTIVE")')->execute([$role,$name,$username,$email,password_hash($password,PASSWORD_DEFAULT)]);$newId=(int)$pdo->lastInsertId();audit_log((int)admin()['id'],'ADMIN_CREATED','admins',(string)$newId,null,['name'=>$name,'role_id'=>$role]);$pdo->commit();flash('success','Administrator created.');}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();flash('error',$e instanceof PDOException?'Could not create administrator. Username or email may exist.':$e->getMessage());}}redirect('/admin/admins/index.php');}
$admins=db()->query('SELECT a.*,r.name role_name FROM admins a JOIN admin_roles r ON r.id=a.role_id ORDER BY a.id')->fetchAll();$roles=db()->query('SELECT * FROM admin_roles ORDER BY id')->fetchAll();$pageTitle='Admins & roles';require APP_ROOT.'/includes/header.php';?>
<?php if(can('admins.create')):?><section class="panel"><h2>Add administrator</h2><form method="post" class="form-grid"><?=csrf_field()?><div class="field"><label>Name</label><input name="name" maxlength="120" required></div><div class="field"><label>Username</label><input name="username" pattern="[A-Za-z0-9._-]{3,80}" required></div><div class="field"><label>Email</label><input name="email" type="email" maxlength="190" required></div><div class="field"><label>Role</label><select name="role_id"><?php foreach($roles as $r):?><option value="<?=e($r['id'])?>"><?=e($r['name'])?></option><?php endforeach?></select></div><div class="field"><label>Temporary password</label><input name="password" type="password" minlength="12" autocomplete="new-password" required></div><div class="field full"><button class="btn">Create administrator</button></div></form></section><?php endif?>
<section class="panel"><div class="panel-head"><h2>Administrator accounts</h2><?php if(can('admins.edit')):?><a href="<?=e(app_url('/admin/admins/roles.php'))?>">Role permissions →</a><?php endif?></div><div class="table-wrap"><table><thead><tr><th>Name</th><th>Username</th><th>Email</th><th>Role</th><th>MFA</th><th>Status</th><th>Last login</th><th></th></tr></thead><tbody><?php foreach($admins as $a):?><tr><td><?=e($a['name'])?></td><td><?=e($a['username'])?></td><td><?=e($a['email'])?></td><td><?=e($a['role_name'])?></td><td><?=$a['mfa_enabled']?'Enabled':'Disabled'?></td><td><span class="badge <?=strtolower(e($a['status']))?>"><?=e($a['status'])?></span></td><td><?=e($a['last_login_at']??'Never')?></td><td><?php if(can('admins.edit')):?><a class="btn small secondary" href="<?=e(app_url('/admin/admins/edit.php?id='.$a['id']))?>">Edit</a><?php endif?></td></tr><?php endforeach?></tbody></table></div></section><?php require APP_ROOT.'/includes/footer.php';

